#!/usr/bin/env python3
"""A sparse run-and-gun dummy plug for N split-screen seats.

Each seat steps into its body (BACK, from the free camera), then holds forward
and the right trigger for the whole run, and now and then turns with the right
stick for a moment. Holds are single events with a duration,
so ten minutes of four players is a few hundred events rather than tens of
thousands. Turns are random but seeded per seat, so runs repeat.

    walk_plug.py run_and_gun_split4.json --seats 4 --duration 600000
"""

import argparse
import json
import random


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("output")
    ap.add_argument("--seats", type=int, default=4)
    ap.add_argument("--duration", type=int, default=600000, help="ms of play per seat")
    ap.add_argument("--start", type=int, default=21000, help="ms before seat 0 steps in, past loading")
    ap.add_argument("--stagger", type=int, default=2000, help="ms between seats starting")
    ap.add_argument("--turn-every", type=int, nargs=2, default=[4000, 9000], help="ms between turns, min max")
    ap.add_argument("--turn-for", type=int, nargs=2, default=[200, 700], help="ms a turn lasts, min max")
    ap.add_argument("--seed", type=int, default=1)
    ap.add_argument("--width", type=int, default=320)
    ap.add_argument("--height", type=int, default=240)
    args = ap.parse_args()

    events = []
    for seat in range(args.seats):
        rng   = random.Random(args.seed * 1000 + seat)
        start = args.start + seat * args.stagger
        end   = start + args.duration
        events.append({"time": 65 + seat * 100, "type": "controller_connect", "index": seat})
        events.append({"time": start, "type": "controller_button", "button": "BACK",
                       "duration": 150, "index": seat})
        walk = start + 1000
        for axis in ("LEFT_Y", "TRIGGER_RIGHT"):
            events.append({"time": walk, "type": "controller_axis", "axis": axis,
                           "value": -1.0 if axis == "LEFT_Y" else 1.0,
                           "duration": end - walk, "index": seat})
        t = walk + rng.randint(*args.turn_every)
        while t < end:
            events.append({"time": t, "type": "controller_axis", "axis": "RIGHT_X",
                           "value": round(rng.choice([-1, 1]) * rng.uniform(.5, 1.), 2),
                           "duration": min(rng.randint(*args.turn_for), end - t), "index": seat})
            t += rng.randint(*args.turn_every)
    events.sort(key=lambda e: (e["time"], e["index"]))

    plug = {
        "graphics": {
            "window": {"width": args.width, "height": args.height, "depth": 24},
            "software_renderer": "llvmpipe",
            "gl": [{"major": 4, "minor": 6}],
            "gles": [],
            "screenshot_quality": 80,
        },
        "audio": {"frequency": 48000, "channels": 2, "format": "f32"},
        "comment": f"{args.seats} split-screen seats run forward firing and turn now and then "
                   f"for {args.duration // 1000} s, generated by walk_plug.py",
        "end_time": args.start + (args.seats - 1) * args.stagger + args.duration + 1000,
        "events": events,
    }
    with open(args.output, "w") as f:
        json.dump(plug, f, indent=4)
        f.write("\n")


if __name__ == "__main__":
    main()
